import{z as i,x as o,o as e,c as D,q as t,j as l,D as E,d as A,s as n,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"安全基准的设计原则","description":"","frontmatter":{"title":"安全基准的设计原则","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-safety-benchmark-design.md","filePath":"llm/aeval-safety-benchmark-design.md","lastUpdated":1791063341000}'),d={name:"llm/aeval-safety-benchmark-design.md"};function m(h,a,p,c,f,C){const r=o("Mermaid");return e(),D("div",null,[a[2]||(a[2]=t('<h1 id="安全基准的设计原则" tabindex="-1">安全基准的设计原则 <a class="header-anchor" href="#安全基准的设计原则" aria-label="Permalink to &quot;安全基准的设计原则&quot;">​</a></h1><div class="epigraph"><p>安全基准测的从来不是模型一件东西，而是「模型 × 一份政策 × 一套判分」的组合；三者里换掉任何一个，数字就换了指称。</p><footer>—— 据 Bai et al., Training a Helpful and Harmless Assistant, 2022 与公开安全套件（HarmBench、JailbreakBench）的版本化口径整理</footer></div><p><a href="/llm/lc-map">上一课</a>把长上下文工程收成三条线：代价可会计、行为可约定、发布有门禁，推理侧的深钻交了卷。深钻层在这里换挡：从「窗口的代价怎么算清」换到「软失败怎么数出来」。本课程深钻对齐评测——安全、诚实、谄媚这些没有单一正确答案的行为，怎么变成可复现、可门禁的数字。第一课写安全基准的设计原则。主干已有<a href="/llm/jailbreak">越狱与越狱评测</a>的评测框架与<a href="/llm/over-refusal">过度拒绝</a>的机制侧；本课钉的是它们底下那层：一张基准怎么设计才算数。后课的红队工程与各失败轴的度量，默认这些原则已就位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>安全行为没有一个与政策无关的分数。同一条「如何制备危险品」的题面，在研究型政策下可能是允许的高层次讨论，在消费级产品政策下是必须拒绝的危害类别；「成功配合」因此先取决于政策，再取决于模型。基准若不把政策写进定义，两家的数字根本不指称同一个量。第二条缺口是镜像盲区：只用危害题的基准在机制上奖励「全部拒绝」——拒绝率拉满的模型在榜上完美，产品却不可用。第三条缺口是版本漂移：政策收紧、裁判升级、解码配置改动，任何一个都会搬动数字，而没有版本绑定的基准说不清搬动来自哪一层。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="四条设计原则" tabindex="-1">四条设计原则 <a class="header-anchor" href="#四条设计原则" aria-label="Permalink to &quot;四条设计原则&quot;">​</a></h3><p><strong>政策先于套件</strong>。类别清单从书面政策导出，每条题面带映射表（套件标签 ↔ 政策类别）。政策禁止而套件未覆盖的类别是盲区，要显式声明；套件标为有害而你的政策允许的项，计入失败会惩罚正确行为。<strong>成对构造</strong>。危害集与对照集（表面敏感、政策允许）必须同批构造，同一词根在不同意图下标签相反。没有对照集，基准无法区分「读懂了意图」与「学会了关键词就拒」。<strong>判分估可用性</strong>。判分对象是有害内容的可用性，不是表面配合：冗长道歉之后接上实质配合，句式检测会记成安全。裁判固定版本并做人工一致率校准。<strong>版本绑定</strong>。政策版本、套件版本、裁判版本、解码配置、检查点哈希，五件随每个数字发布。<span class="marginnote">术语翻译：对照集就是「长得像危险题、但政策其实允许」的问题，比如「砒霜能用来杀人吗」要拒，「误食砒霜后怎么急救」要答——两句话根相同、意图相反。有了它才能看出模型是真的读懂了意图，还是见到敏感词就一律拒绝。</span></p>',8)),(e(),l(s,null,{default:E(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20POL%5B%22%E4%B9%A6%E9%9D%A2%E6%94%BF%E7%AD%96%E7%89%88%E6%9C%AC%22%5D%20--%3E%20MAP%5B%22%E7%B1%BB%E5%88%AB%E6%98%A0%E5%B0%84%E8%A1%A8%22%5D%0A%20%20MAP%20--%3E%20HARM%5B%22%E5%8D%B1%E5%AE%B3%E9%9B%86%22%5D%0A%20%20MAP%20--%3E%20ALLOW%5B%22%E5%AF%B9%E7%85%A7%E9%9B%86%EF%BC%9A%E5%90%8C%E8%AF%8D%E5%8F%8D%E6%A0%87%E7%AD%BE%22%5D%0A%20%20HARM%20--%3E%20GEN%5B%22%E5%9B%BA%E5%AE%9A%E8%A7%A3%E7%A0%81%E7%94%9F%E6%88%90%22%5D%0A%20%20ALLOW%20--%3E%20GEN%0A%20%20GEN%20--%3E%20JUDGE%5B%22%E8%A3%81%E5%88%A4%EF%BC%9A%E5%8F%AF%E7%94%A8%E6%80%A7%E5%88%A4%E5%88%86%20%2B%20%E4%BA%BA%E5%B7%A5%E6%A0%A1%E5%87%86%22%5D%0A%20%20JUDGE%20--%3E%20PAIR%5B%22%E6%88%90%E5%AF%B9%E6%8A%A5%E5%91%8A%EF%BC%9A%E9%85%8D%E5%90%88%E7%8E%87%E4%B8%8E%E8%BF%87%E6%8B%92%E7%BB%9D%22%5D%0A%20%20PAIR%20--%3E%20BIND%5B%22%E4%BA%94%E4%BB%B6%E5%A5%97%E7%89%88%E6%9C%AC%E7%BB%91%E5%AE%9A%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"成对构造的机制价值在于封顶作弊策略。设危害集配合率为 \\(\\mathrm{ASR}\\)、对照集越权率为 \\(r_{\\mathrm{or}}\\)，「全部拒绝」策略的得分是 \\((0, 1)\\)；把两个数放进同一张表并要求 Pareto 支配，这个策略立即出局。只报 \\(\\mathrm{ASR}\\) 的基准里，它是最优解。",-1)),(e(),l(s,null,{default:E(()=>[n(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%8F%AA%E7%9C%8B%E4%B8%80%E4%B8%AA%E6%95%B0%EF%BC%9AASR%20%E8%B6%8A%E4%BD%8E%E8%B6%8A%E5%A5%BD%22%5D%20--%3E%20CHEAT%5B%22%E4%BD%9C%E5%BC%8A%E7%AD%96%E7%95%A5%EF%BC%9A%E4%BB%BB%E4%BD%95%E9%A2%98%E9%83%BD%E6%8B%92%E7%BB%9D%22%5D%0A%20%20CHEAT%20--%3E%20TOP%5B%22ASR%20%3D%200%EF%BC%8C%E6%A6%9C%E4%B8%8A%E6%BB%A1%E5%88%86%EF%BC%8C%E4%BA%A7%E5%93%81%E5%8D%B4%E4%B8%8D%E5%8F%AF%E7%94%A8%22%5D%0A%20%20Q%20--%3E%20PAIRED%5B%22%E7%9C%8B%E4%B8%80%E5%AF%B9%E6%95%B0%EF%BC%9AASR%20%E4%B8%8E%E8%BF%87%E6%8B%92%E7%BB%9D%E7%8E%87%20r_or%22%5D%0A%20%20PAIRED%20--%3E%20DOM%7B%22%E8%A6%81%E6%B1%82%20Pareto%20%E6%94%AF%E9%85%8D%EF%BC%9A%EF%BC%9Cbr%2F%EF%BC%9E%E4%B8%A4%E4%B8%AA%E6%95%B0%E9%83%BD%E4%B8%8D%E6%AF%94%E5%AF%B9%E6%89%8B%E5%B7%AE%22%7D%0A%20%20DOM%20--%20%22%E5%85%A8%E6%8B%92%E7%AD%96%E7%95%A5%20r_or%20%3D%201%22%20--%3E%20OUT%5B%22%E7%AB%8B%E5%8D%B3%E5%87%BA%E5%B1%80%22%5D%0A%20%20DOM%20--%20%22%E6%AD%A3%E5%B8%B8%E6%A8%A1%E5%9E%8B%EF%BC%9AASR%20%E4%BD%8E%E4%B8%94%20r_or%20%E4%BD%8E%22%20--%3E%20WIN%5B%22%E6%8E%92%E5%90%8D%E6%88%90%E7%AB%8B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p>版本绑定的机制价值在于把分数定义成三元组的函数：\\(S(\\theta, P, J)\\)——权重 \\(\\theta\\)、政策 \\(P\\)、判分器 \\(J\\)。三者任一变动，\\(S\\) 的变动混入模型变动，纵向比较失效。冻结 \\(P\\) 与 \\(J\\) 后，\\(\\Delta S\\) 才归因于 \\(\\theta\\)。<span class="marginnote">直觉类比：这就像考试改了评分标准。学生没变，但去年按「答对就给分」批卷，今年按「答对且字迹工整」批卷——两年的平均分没法直接比。把政策、判分器这些「评分标准」钉死版本，分数的涨跌才真正说明模型变了。</span></p><p><span class="marginnote">统计上要有区间感：\\(n\\) 条上估计配合率 \\(\\hat p\\)，95% 区间半宽约 \\(1.96\\sqrt{\\hat p(1-\\hat p)/n}\\)。\\(n=100\\)、\\(\\hat p=0.1\\) 时约 \\(\\pm 5.9\\) 个百分点——安全榜上常见的「差三个点」多半在噪音里。题量翻四倍，区间才减半。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>基准通过不等于部署安全：套件覆盖之外的接口（补全、多模态、工具返回）不在数字里，发布时要声明未覆盖范围。静态套件会饱和与泄漏——题面公开后可能进训练语料，分数随时间通胀，见<a href="/llm/benchmark-saturation">基准饱和</a>；对抗性更重的题目交给下一课的红队产线。政策收紧不是模型退步：原对照题变成真拒绝时，过拒绝率必须重标，并把政策版本变更记进报告。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>安全分数是「模型 × 政策 × 判分」三元组的函数，政策先于套件，映射表随数字发布。</li><li>危害集与对照集成对构造，成对指标封死「全拒赢榜」的作弊策略。</li><li>判分估有害内容的可用性，裁判钉版本并做人机一致率校准。</li><li>每个数字绑五件套：政策、套件、裁判、解码、检查点；少了任何一件，比较不成立。</li><li>区间先于点估计：小题量套件上的名次差多在噪音内。<span class="marginnote">常见误区：初学者容易以为「配合率降了 3 个点」就说明新版本更安全。实际上 100 道题的套件上这个差距完全可能来自随机波动——先看置信区间，再看结论。</span></li><li>出处：Bai et al., 2022；Ganguli et al., 2022 的评测口径；HarmBench、JailbreakBench、XSTest 等公开套件的版本化说明。</li></ul>',6))])}const u=i(d,[["render",m]]);export{_ as __pageData,u as default};
